#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Generate fixed-temperature HH equilibrium/fraction tables from the reference.

The 0.25 mV grid is linearly interpolated; it does not quantise membrane voltage.
Fractions are 1-exp(-rate*0.0125 ms) for the normal 0.025 ms internal step.
Run --check to verify the committed header without changing it.
"""
import argparse
import math
from pathlib import Path
from vc_hh_reference import rates


def generate():
    lines=['/* SPDX-License-Identifier: GPL-3.0-or-later */', '#pragma once',
      '// Generated by Firmware/tools/generate_vc_gate_table.py; do not edit.',
      '// Canonical HH at 6.3 C; -250..250 mV in 0.25 mV increments.',
      'namespace vc {',
      'struct GateTableEntry { float infinity[3]; float fraction[3]; };',
      'inline constexpr unsigned gate_table_size = 2001;',
      'inline constexpr GateTableEntry gate_table[gate_table_size] = {']
    def literal(v):
        text=format(v,'.9g')
        if '.' not in text and 'e' not in text:text+='.0'
        return text+'f'
    for i in range(2001):
        kinetics=rates(-250+i*.25)
        inf=', '.join(literal(a) for a,b in kinetics)
        fraction=', '.join(literal(-math.expm1(-b*.0125)) for a,b in kinetics)
        lines.append('  {{'+inf+'}, {'+fraction+'}},')
    lines+=['};','} // namespace vc','']
    return '\n'.join(lines)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--output',type=Path,default=Path(__file__).resolve().parents[1]/
                        'Spikeling_V3/VoltageClamp_gate_table.h')
    args=parser.parse_args()
    text=generate()
    if args.check:
        if args.output.read_text()!=text:raise SystemExit('Gate table differs; regenerate it')
        print('Gate table matches generator')
    else:
        args.output.write_text(text)
        print('Generated '+str(args.output))


if __name__=='__main__':main()
